  // Runs a separate headless experiment to completion; does not touch the view.
  simulate(overrides = {}, seconds = SIM.maxTime) {
    const e = new Experiment({ ...DEFAULTS, ...overrides });
    e.start();
    const frames = Math.round(seconds / SIM.frameDt);
    for (let i = 0; i < frames && e.running; i++) e.stepFrame();
    return e.summary();
  },
};

